1	// src/lib/land/seite.js – Land einer Seite auf dem Server (nutzt react/cache und next/navigation)
2	//
3	// Getrennt von index.js, damit node:test, next.config.mjs, Middleware und Client-Komponenten die
4	// reine Länderlogik ohne Server-Funktionen laden können.
5	//
6	// Jede öffentliche Seite (src/app/(stamm)/…/page.js) ist zugleich ihre Länderfassung: Die Route
7	// src/app/(laender)/[land]/…/page.js exportiert genau diese Seite weiter, Next.js reicht dabei
8	// params.land ("de" | "at" | "ch") durch. Die Seite ruft am Anfang
9	//
10	//   const land = await seitenLand(params);          // "DE" | "AT" | "CH" | null (= gemeinsam)
11	//
12	// und exportiert ihre Metadaten über
13	//
14	//   export const generateMetadata = seitenMetadata("/rechner/pacht", metadata);
15	//
16	// Tiefer liegende Server-Komponenten (z. B. RechnerSeite) lesen das Land danach mit
17	// landDerAnfrage() – ohne es durchreichen zu müssen. Client-Komponenten nutzen useLand()
18	// (src/components/Land/useLand.js), das Land kommt dort aus dem Root-Layout.
19	
20	import { cache } from "react";
21	import { notFound } from "next/navigation";
22	import { landAusPraefix } from "./laender.js";
23	import { alternates, fassungIndexierbar, ogLocale } from "./pfad.js";
24	import { spracheOder } from "../sprache/sprachen.js";
25	import { setzeLandQuelle, uebersetze } from "../sprache/woerterbuch.js";
26	import { schreibweiseFuer, setzeAusgabeLand } from "./schreibweise.js";
27	
28	/** Speicher je Anfrage (React cache): Land und Sprache der gerade gerenderten Seite. */
29	const anfrage = cache(() => ({ land: null, sprache: "de", gesetzt: false }));
30	
31	// Server-Komponenten rufen uebersetze(TEXTE, sprache) ohne Land: Das Land der Anfrage kommt von
32	// hier (Schweizer Schreibweise ohne „ß“ auf /ch und /en/ch, src/lib/land/schreibweise.js).
33	setzeLandQuelle(() => anfrage().land);
34	setzeAusgabeLand(() => anfrage().land); // JSON-LD auf /ch ohne „ß“ (src/components/JsonLd.js)
35	
36	/**
37	 * Sprache aus den Routenparametern: Die englischen Routen (src/app/(en)/en/…, erzeugt mit
38	 * scripts/landfassungen.mjs) reichen params.sprache = "en" an dieselbe Seitenkomponente durch
39	 * (src/lib/sprache/route.js). Ohne Angabe: Deutsch.
40	 */
41	export const spracheAusParams = (p) => spracheOder(p?.sprache);
42	
43	/**
44	 * Land aus den Routenparametern. Ohne params.land: gemeinsame Seite (null).
45	 * Unbekanntes Präfix → 404. Merkt sich das Land für landDerAnfrage().
46	 * @param {Promise<object>|object} params
47	 * @returns {Promise<"DE"|"AT"|"CH"|null>}
48	 */
49	export async function seitenLand(params) {
50	  const p = (await params) || {};
51	  let land = null;
52	  if (p.land !== undefined) {
53	    land = landAusPraefix(p.land);
54	    if (!land) notFound();
55	  }
56	  const a = anfrage();
57	  a.land = land;
58	  a.sprache = spracheAusParams(p);
59	  a.gesetzt = true;
60	  return land;
61	}
62	
63	/**
64	 * Land der aktuellen Seite für Server-Komponenten unterhalb der Seite.
65	 * Nur gültig, nachdem die Seite seitenLand(params) aufgerufen hat (sonst null = gemeinsam).
66	 */
67	export function landDerAnfrage() {
68	  return anfrage().land;
69	}
70	
71	/**
72	 * Sprache der aktuellen Seite ("de" | "en") für Server-Komponenten unterhalb der Seite.
73	 * Nur gültig, nachdem die Seite seitenLand(params) aufgerufen hat (sonst "de").
74	 */
75	export function spracheDerAnfrage() {
76	  return anfrage().sprache;
77	}
78	
79	/**
80	 * generateMetadata für eine öffentliche Seite (gemeinsam, Länderfassung, englische Fassung):
81	 * übernimmt die Basis-Metadaten und setzt canonical, hreflang, og:url und og:locale.
82	 * Noindex bekommen Länderfassungen ohne eigenen Länderinhalt (Register src/lib/land/seiten.js)
83	 * und englische Fassungen, die noch nicht übersetzt sind (src/lib/sprache/seiten.js).
84	 * @param {string | ((p: object) => string)} schluessel Pfad ohne Präfix (bei [slug]-Routen aus params)
85	 * @param {object | ((land: string|null, p: object) => object|Promise<object>)} basis  p.sprache = "de" | "en"
86	 * @param {{ en?: object | ((de: object) => object) }} [woerterbuch] englische Metadaten (title,
87	 *   description, openGraph.title …), tief über die deutschen gelegt (uebersetze()).
88	 */
89	export function seitenMetadata(schluessel, basis, woerterbuch = {}) {
90	  return async function generateMetadata({ params }) {
91	    const p = (await params) || {};
92	    const land = p.land !== undefined ? landAusPraefix(p.land) : null;
93	    const sprache = spracheAusParams(p);
94	    const konkret = typeof schluessel === "function" ? schluessel(p) : schluessel;
95	    const roh = (typeof basis === "function" ? await basis(land, p) : basis) || {};
96	    const b = sprache === "en" && woerterbuch?.en ? uebersetze({ de: roh, en: woerterbuch.en }, "en") : roh;
97	    const a = alternates(konkret, land, { languages: b.alternates?.languages, sprache });
98	    const index = land || sprache !== "de" ? fassungIndexierbar(konkret, land, sprache) : null;
99	    const locale = land || sprache !== "de" ? { locale: ogLocale(land, sprache) } : {};
100	    return schreibweiseFuer({
101	      ...b,
102	      alternates: { ...(b.alternates || {}), ...a, ...(a.languages ? {} : { languages: undefined }) },
103	      ...(b.openGraph ? { openGraph: { ...b.openGraph, url: a.canonical, ...locale } } : {}),
104	      ...(index === false ? { robots: { index: false, follow: true } } : {}),
105	    }, land);
106	  };
107	}
108

1	#!/usr/bin/env node
2	// scripts/landfassungen.mjs – Länder- und Sprachfassungen der öffentlichen Seiten erzeugen und prüfen
3	//
4	//   node scripts/landfassungen.mjs             Routen schreiben:
5	//                                                src/app/(laender)/[land]/…   /de|at|ch/<seite>
6	//                                                src/app/(en)/en/…            /en/<seite>
7	//                                                src/app/(en)/en/[land]/…     /en/de|at|ch/<seite>
8	//   node scripts/landfassungen.mjs --pruefen   nur prüfen: Exit 1, wenn eine Route fehlt, abweicht
9	//                                              oder keine Seite im Register (src/lib/land/seiten.js) hat
10	//
11	// Sprachfassungen (Sprachmodell, src/lib/sprache): Die englischen Routen reichen DIESELBE Seite
12	// weiter und setzen nur params.sprache = "en" (src/lib/sprache/route.js):
13	//
14	//   import Seite, { generateMetadata as metadaten } from "@/app/(stamm)/rechner/pacht/page";
15	//   import { englisch, englischeMetadaten } from "@/lib/sprache/route";
16	//   export default englisch(Seite);
17	//   export const generateMetadata = englischeMetadaten(metadaten);
18	//
19	// Jede Seite aus SEITEN existiert gemeinsam unter src/app/(stamm)/<pfad>/page.js. Ihre
20	// Länderfassung ist eine reine Weiterleitung auf DIESELBE Seitenkomponente – kein Kopieren:
21	//
22	//   import Seite from "@/app/(stamm)/rechner/pacht/page";
23	//   import { landSeite } from "@/components/Land/LandSeite";
24	//   export default landSeite(Seite);
25	//   export { generateMetadata } from "@/app/(stamm)/rechner/pacht/page";
26	//
27	// landSeite() (src/components/Land/LandSeite.js) gibt die Seite unverändert weiter; nur in der
28	// Schweiz (/ch, /en/ch) schreibt es alle Texte der Seite ohne „ß“ (Schweizer Schreibweise).
29	//
30	// Next.js reicht params.land ("de" | "at" | "ch") an die Seite durch; die Seite liest es mit
31	// seitenLand(params). Routen-Einstellungen (dynamic, revalidate, dynamicParams …) muss Next.js
32	// statisch in der Datei sehen – sie werden als Literal übernommen; generateStaticParams wird
33	// weitergereicht.
34	
35	import { existsSync, mkdirSync, readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
36	import { dirname, join, relative, resolve, sep } from "node:path";
37	import { fileURLToPath } from "node:url";
38	import { SEITEN } from "../src/lib/land/seiten.js";
39	
40	const WURZEL = resolve(dirname(fileURLToPath(import.meta.url)), "..");
41	const APP = join(WURZEL, "src", "app");
42	const GEMEINSAM = join(APP, "(stamm)");
43	const LAND = join(APP, "(laender)", "[land]");
44	const EN = join(APP, "(en)", "en");
45	const EN_LAND = join(EN, "[land]");
46	const pruefen = process.argv.includes("--pruefen");
47	
48	const KONFIG = /^export const (dynamic|revalidate|dynamicParams|fetchCache|runtime|preferredRegion|maxDuration) = ("[^"\n]*"|\d+|true|false);\s*$/gm;
49	
50	/**
51	 * Einstellungen, die nur für die gemeinsame Seite gelten: Die Startseite „/“ ist dynamisch und
52	 * wird nie zwischengespeichert (Entscheidung 6: Weiterleitung nur mit Cookie „land“, Middleware);
53	 * ihre Länderfassungen /de, /at, /ch bleiben statisch.
54	 */
55	const NUR_GEMEINSAM = { "/": ["dynamic"] };
56	
57	const datei = (basis, k) => join(basis, ...(k === "/" ? [] : k.slice(1).split("/")), "page.js");
58	
59	/** Inhalt der Länderroute für einen Schlüssel. */
60	export function landRoute(k, quelle) {
61	  const modul = `@/app/(stamm)${k === "/" ? "" : k}/page`;
62	  const namen = [];
63	  if (/export (const|async function|function) generateMetadata\b/.test(quelle)) namen.push("generateMetadata");
64	  if (/export (const|async function|function) generateStaticParams\b/.test(quelle)) namen.push("generateStaticParams");
65	  const konfig = [...quelle.matchAll(KONFIG)].filter((m) => !(NUR_GEMEINSAM[k] || []).includes(m[1])).map((m) => `export const ${m[1]} = ${m[2]};`);
66	  return [
67	    `// Länderfassung von ${k} (/de, /at, /ch) – erzeugt mit scripts/landfassungen.mjs, nicht von Hand ändern.`,
68	    `// Dieselbe Seite wie src/app/(stamm)${k === "/" ? "" : k}/page.js; das Land kommt aus params.land.`,
69	    `import Seite from "${modul}";`,
70	    `import { landSeite } from "@/components/Land/LandSeite";`,
71	    `export default landSeite(Seite);`,
72	    ...(namen.length ? [`export { ${namen.join(", ")} } from "${modul}";`] : []),
73	    ...konfig,
74	    "",
75	  ].join("\n");
76	}
77	
78	/** Inhalt der englischen Route (gemeinsam oder Land) für einen Schlüssel. */
79	export function enRoute(k, quelle, { land = false } = {}) {
80	  const modul = `@/app/(stamm)${k === "/" ? "" : k}/page`;
81	  const statisch = /export (const|async function|function) generateStaticParams\b/.test(quelle);
82	  const konfig = [...quelle.matchAll(KONFIG)].filter((m) => !(NUR_GEMEINSAM[k] || []).includes(m[1])).map((m) => `export const ${m[1]} = ${m[2]};`);
83	  return [
84	    `// Englische Fassung von ${k} (${land ? "/en/de, /en/at, /en/ch" : "/en"}) – erzeugt mit scripts/landfassungen.mjs, nicht von Hand ändern.`,
85	    `// Dieselbe Seite wie src/app/(stamm)${k === "/" ? "" : k}/page.js; Sprache "en" über params.sprache${land ? ", das Land aus params.land" : ""}.`,
86	    `import Seite, { generateMetadata as metadaten } from "${modul}";`,
87	    `import { englisch, englischeMetadaten } from "@/lib/sprache/route";`,
88	    ...(land ? [`import { landSeite } from "@/components/Land/LandSeite";`, `export default landSeite(englisch(Seite));`] : [`export default englisch(Seite);`]),
89	    `export const generateMetadata = englischeMetadaten(metadaten);`,
90	    ...(statisch ? [`export { generateStaticParams } from "${modul}";`] : []),
91	    ...konfig,
92	    "",
93	  ].join("\n");
94	}
95	
96	function seiten(dir, liste = []) {
97	  for (const n of readdirSync(dir)) {
98	    const p = join(dir, n);
99	    if (statSync(p).isDirectory()) seiten(p, liste);
100	    else if (n === "page.js") liste.push(p);
101	  }
102	  return liste;
103	}
104	
105	const fehler = [];
106	let geschrieben = 0;
107	for (const k of Object.keys(SEITEN)) {
108	  const q = datei(GEMEINSAM, k);
109	  if (!existsSync(q)) {
110	    fehler.push(`gemeinsame Seite fehlt: ${relative(WURZEL, q)}`);
111	    continue;
112	  }
113	  const quelle = readFileSync(q, "utf8");
114	  if (!/seitenLand\(params\)/.test(quelle)) fehler.push(`${k}: Seite ruft seitenLand(params) nicht auf`);
115	  if (!/seitenMetadata\(/.test(quelle)) fehler.push(`${k}: Metadaten nicht über seitenMetadata()`);
116	  if (/export const metadata\b/.test(quelle)) fehler.push(`${k}: statische metadata – Länderfassung bekäme kein eigenes canonical/noindex`);
117	  for (const [ziel, soll] of [
118	    [datei(LAND, k), landRoute(k, quelle)],
119	    [datei(EN, k), enRoute(k, quelle)],
120	    [datei(EN_LAND, k), enRoute(k, quelle, { land: true })],
121	  ]) {
122	    const ist = existsSync(ziel) ? readFileSync(ziel, "utf8").replace(/\r\n/g, "\n") : null;
123	    if (ist === soll) continue;
124	    if (pruefen) fehler.push(`${relative(WURZEL, ziel)} ${ist === null ? "fehlt" : "weicht ab"} (node scripts/landfassungen.mjs)`);
125	    else {
126	      mkdirSync(dirname(ziel), { recursive: true });
127	      writeFileSync(ziel, soll);
128	      geschrieben++;
129	    }
130	  }
131	}
132	
133	// Umgekehrt: keine Länder- oder Sprachroute ohne Registereintrag
134	// Ausnahme: die 404-Fänger für unbekannte Unterseiten ([...unbekannt], rufen nur notFound() auf,
135	// damit die 404 im Länder- bzw. englischen Root-Layout mit passendem lang erscheint).
136	const FAENGER = [join(LAND, "[...unbekannt]", "page.js"), join(EN_LAND, "[...unbekannt]", "page.js")];
137	const bekannt = new Set([...FAENGER, ...Object.keys(SEITEN).flatMap((k) => [datei(LAND, k), datei(EN, k), datei(EN_LAND, k)])]);
138	for (const d of [...seiten(LAND), ...(existsSync(EN) ? seiten(EN) : [])]) if (!bekannt.has(d)) fehler.push(`Länder-/Sprachroute ohne Registereintrag: ${relative(WURZEL, d).split(sep).join("/")}`);
139	
140	if (fehler.length) {
141	  console.error(`Länder- und Sprachfassungen: ${fehler.length} Fehler`);
142	  for (const f of fehler) console.error("  - " + f);
143	  process.exit(1);
144	}
145	console.log(pruefen ? `Länder- und Sprachfassungen: ${Object.keys(SEITEN).length} Seiten × 3 Routen, alle vorhanden und aktuell.` : `Länder- und Sprachfassungen: ${geschrieben} Routen geschrieben (${Object.keys(SEITEN).length} Seiten).`);
146

