let ausgewogenKwp = 0;
if (verbrauch > 0) {
  let lo = 0.5;
  let hi = Math.max(kwp, 1);
  const evVon = (k) => {
    const erz = k * region.ertrag * dach.ertragFaktor;
    return erz > 0 ? geteilteMenge(erz, verbrauch, a) / erz : 1;
