  if (evVon(hi) >= 0.5) ausgewogenKwp = hi;
  else {
    for (let i = 0; i < 40; i++) {
      const mitte = (lo + hi) / 2;
      if (evVon(mitte) >= 0.5) lo = mitte;
      else hi = mitte;
    }
    ausgewogenKwp = lo;
  }
}

