import { ANNAHMEN, DACHARTEN, GEBAEUDETYPEN, LAENDER, rechneGebaeudestrom, regionenFuer, selbsttest, standardFuer } from "./gebaeudestrom.js";

test("Selbsttest läuft fehlerfrei", () => {
